1	//! Which props of a component evidence puts forward (ADR 0028, section A).
2	//!
3	//! [`decide`] is the one place the rules are combined: it takes the [`Evidence`] gathered for the members a
4	//! component's props type reaches and says, for each member, whether it is a typed row, a name in its collapsed
5	//! layer's `used` list, left in that layer, or unknown because the body says nothing. It is pure and total: no I/O, no
6	//! name lists, and its output follows the order of the members it is given.
7	//!
8	//! [`apply`] is its one caller, where a structural answer becomes output (`pipeline::revision`): the [`Inputs`]
9	//! gathered with the answer's resolution (so their reads are its dependencies) and the revision's call-site counts
10	//! (counted again each revision, so an edit to a consumer reaches every component it renders). The checker's merges
11	//! keep the inheritance layers, and so the `used` lists, of the structural answer.
12	
13	pub(crate) mod call_sites;
14	pub(crate) mod forwarding;
15	pub(crate) mod props_type;
16	
17	use std::collections::BTreeSet;
18	
19	use crate::types::output::ComponentEntry;
20	
21	/// The evidence about one component gathered with its resolution: what its props type writes and what its body does.
22	#[derive(Debug, Clone, PartialEq, Eq)]
23	pub(crate) struct Inputs {
24	    /// The component's place in the project, which its call-site count is looked up by.
25	    pub(crate) site: call_sites::SiteKey,
26	    /// What the props type writes itself.
27	    pub(crate) props_type: props_type::PropsType,
28	    /// What the component's body does with its props; `None` when it has no function of its own.
29	    pub(crate) body: Option<Body>,
30	}
31	
32	/// Decides where each member of `entry`'s props goes, from `inputs`, the revision's `call_sites` of the component and
33	/// the members its listed props and layers reach, and writes each collapsed layer's `used` list: the members of that
34	/// layer evidence names. Which props are listed or collapsed does not change.
35	pub(crate) fn apply(entry: &mut ComponentEntry, inputs: &Inputs, call_sites: &CallSites) {
36	    let rows = entry.props.values().chain(entry.notable_inherited.values()).map(AsRef::as_ref);
37	    let members = props_type::members(&inputs.props_type, rows, &entry.inheritance);
38	    let shown = decide(&Evidence { members: &members, body: inputs.body.as_ref(), call_sites });
39	    let used: BTreeSet<&str> = shown.used.iter().map(String::as_str).collect();
40	    for layer in &mut entry.inheritance {
41	        layer.used = layer.members.iter().filter(|name| used.contains(name.as_str())).cloned().collect();
42	    }
43	}
44	
45	/// Everything known about the members one component's props type reaches.
46	#[derive(Debug, Clone, Copy)]
47	pub(crate) struct Evidence<'a> {
48	    /// The members, in the order the props type reaches them; [`Shown`] keeps this order. A name repeated is placed
49	    /// once, by its first member.
50	    pub(crate) members: &'a [Member],
51	    /// What the component's own function body does with its props; `None` when it has no function of its own.
52	    pub(crate) body: Option<&'a Body>,
53	    /// The props passed at the component's JSX call sites across the project.
54	    pub(crate) call_sites: &'a CallSites,
55	}
56	
57	/// One member the props type reaches, with the signals its declaration gives.
58	#[derive(Debug, Clone, Default, PartialEq, Eq)]
59	pub(crate) struct Member {
60	    /// The member's name. Only compared with other names in the same [`Evidence`], never with a list.
61	    pub(crate) name: String,
62	    /// The props type declares it itself, not through an inherited source.
63	    pub(crate) own: bool,
64	    /// A key a `Pick<X, …>` names.
65	    pub(crate) picked: bool,
66	    /// It redeclares or narrows a base member.
67	    pub(crate) overrides: bool,
68	    /// It is not optional.
69	    pub(crate) required: bool,
70	    /// Its declaration carries a `@default` tag.
71	    pub(crate) default_tag: bool,
72	    /// It carries a JSDoc comment: orders the rows, never shows a member.
73	    pub(crate) documented: bool,
74	    /// Its type is a union of literals: orders the rows, never shows a member.
75	    pub(crate) literal_union: bool,
76	    /// Declared by React's or the shared DOM declarations ([`crate::origin::Origin::is_ambient`]): decided by
77	    /// the declaring path, never by the name.
78	    pub(crate) ambient: bool,
79	}
80	
81	/// What a component's function body does with its props, read from the syntax alone.
82	#[derive(Debug, Clone, Default, PartialEq, Eq)]
83	pub(crate) struct Body {
84	    /// The props the body reads. Complete only when [`Body::is_complete`].
85	    pub(crate) reads: Vec<String>,
86	    /// The JSX elements the body writes, in source order.
87	    pub(crate) elements: Vec<Element>,
88	    /// The props object or a rest binding escapes in a way the syntax cannot follow: what the body says still holds,
89	    /// but its silence about a prop is unknown, never guessed.
90	    pub(crate) handed_on: bool,
91	}
92	
93	/// One JSX element a component body writes.
94	#[derive(Debug, Clone, PartialEq, Eq)]
95	pub(crate) struct Element {
96	    /// What the tag resolves to.
97	    pub(crate) target: Target,
98	    /// Its attributes in source order, so a named attribute's place before or after a spread is kept.
99	    pub(crate) attributes: Vec<Attribute>,
100	}
101	
102	/// What a JSX tag resolves to.
103	#[derive(Debug, Clone, PartialEq, Eq)]
104	pub(crate) enum Target {
105	    /// A host element: a spread onto it passes only ambient DOM attributes.
106	    Dom,
107	    /// A component resolved by symbol and import, with the names of its own non-ambient props.
108	    Component(Vec<String>),
109	    /// A component tag that did not resolve: a spread onto it leaves the body's evidence unknown.
110	    Unresolved,
111	}
112	
113	/// One attribute of a JSX element.
114	#[derive(Debug, Clone, PartialEq, Eq)]
115	pub(crate) enum Attribute {
116	    /// `name={value}`: set after a spread, it fixes `name`; its value adds nothing.
117	    Named(String),
118	    /// `{...value}`.
119	    Spread(SpreadOf),
120	}
121	
122	/// What a JSX spread attribute spreads.
123	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
124	pub(crate) enum SpreadOf {
125	    /// The props object, whole.
126	    Props,
127	    /// A rest binding of the props object.
128	    Rest,
129	    /// Any other expression: no evidence about the props.
130	    Other,
131	}
132	
133	/// How often each prop is passed at a component's JSX call sites.
134	#[derive(Debug, Clone, Default, PartialEq, Eq)]
135	pub(crate) struct CallSites {
136	    /// The number of call sites.
137	    pub(crate) sites: u32,
138	    /// Each prop passed at them, with the number of sites passing it.
139	    pub(crate) passed: Vec<(String, u32)>,
140	}
141	
142	/// No call sites: no evidence.
143	pub(crate) static NO_CALL_SITES: CallSites = CallSites { sites: 0, passed: Vec::new() };
144	
145	impl CallSites {
146	    /// Whether `count` of the sites reach the floor of `max(2, 20%)` of them.
147	    fn at_floor(&self, count: u32) -> bool {
148	        count >= 2 && u64::from(count) * 5 >= u64::from(self.sites)
149	    }
150	}
151	
152	/// Where [`decide`] puts each member, every list in the order of [`Evidence::members`], except that `rows` puts the
153	/// documented and literal-union members first.
154	#[derive(Debug, Clone, Default, PartialEq, Eq)]
155	pub(crate) struct Shown {
156	    /// Typed rows.
157	    pub(crate) rows: Vec<String>,
158	    /// Ambient members named in their collapsed layer's `used` list: passed at the floor or read.
159	    pub(crate) used: Vec<String>,
160	    /// Members left in their collapsed layer.
161	    pub(crate) collapsed: Vec<String>,
162	    /// Members with no signal whose body evidence is incomplete or absent: listed or collapsed by the collapse rule
163	    /// alone, so missing evidence never hides more than that rule does.
164	    pub(crate) unknown: Vec<String>,
165	}
166	
167	/// Decides, from the evidence alone, where each member of a component's props goes.
168	pub(crate) fn decide(evidence: &Evidence<'_>) -> Shown {
169	    let body = evidence.body;
170	    let complete = body.is_some_and(Body::is_complete);
171	    let reads: BTreeSet<&str> = body.map(|body| body.reads.iter().map(String::as_str).collect()).unwrap_or_default();
172	    let forwarded = body.map(Body::forwarded).unwrap_or_default();
173	    let passed: BTreeSet<&str> = evidence
174	        .call_sites
175	        .passed
176	        .iter()
177	        .filter(|(_, count)| evidence.call_sites.at_floor(*count))
178	        .map(|(name, _)| name.as_str())
179	        .collect();
180	    let mut shown = Shown::default();
181	    let mut ordered_rows = Vec::new();
182	    let mut placed = BTreeSet::new();
183	    for member in evidence.members {
184	        let name = member.name.as_str();
185	        if !placed.insert(name) {
186	            continue;
187	        }
188	        let declared = member.own || member.picked || member.overrides || member.required || member.default_tag;
189	        // Passed at the floor or read puts a member forward: a typed row unless ambient, then a name in its layer's
190	        // `used` list (ADR 0028, Combination).
191	        let wanted = passed.contains(name) || reads.contains(name);
192	        let list = if declared || (!member.ambient && (wanted || forwarded.contains(name))) {
193	            ordered_rows.push((!(member.documented || member.literal_union), member.name.clone()));
194	            continue;
195	        } else if member.ambient && wanted {
196	            &mut shown.used
197	        } else if !complete {
198	            &mut shown.unknown
199	        } else {
200	            &mut shown.collapsed
201	        };
202	        list.push(member.name.clone());
203	    }
204	    ordered_rows.sort_by_key(|(plain, _)| *plain);
205	    shown.rows = ordered_rows.into_iter().map(|(_, name)| name).collect();
206	    shown
207	}
208	
209	impl Body {
210	    /// Whether the body's evidence is complete, so that a prop it never mentions is known to be unused: nothing handed
211	    /// on, and no spread of the props onto a tag that did not resolve. What an incomplete body does say (a read, a
212	    /// default, a forward) is still certain; only its silence is unknown.
213	    fn is_complete(&self) -> bool {
214	        !self.handed_on
215	            && !self.elements.iter().any(|element| {
216	                element.target == Target::Unresolved
217	                    && element.attributes.iter().any(|attribute| attribute.spreads_props())
218	            })
219	    }
220	
221	    /// The props a spread of the props object or a rest binding passes one hop on to a component: the component's own
222	    /// props, minus those an attribute after the spread fixes. Spreads onto DOM tags pass nothing.
223	    fn forwarded(&self) -> BTreeSet<&str> {
224	        let mut forwarded = BTreeSet::new();
225	        for element in &self.elements {
226	            let Target::Component(own) = &element.target else { continue };
227	            for (at, attribute) in element.attributes.iter().enumerate() {
228	                if !attribute.spreads_props() {
229	                    continue;
230	                }
231	                let fixed: BTreeSet<&str> = element.attributes[at + 1..]
232	                    .iter()
233	                    .filter_map(|after| match after {
234	                        Attribute::Named(name) => Some(name.as_str()),
235	                        Attribute::Spread(_) => None,
236	                    })
237	                    .collect();
238	                forwarded.extend(own.iter().map(String::as_str).filter(|name| !fixed.contains(name)));
239	            }
240	        }
241	        forwarded
242	    }
243	}
244	
245	impl Attribute {
246	    /// Whether the attribute spreads the props object or a rest binding of it.
247	    fn spreads_props(&self) -> bool {
248	        matches!(self, Self::Spread(SpreadOf::Props | SpreadOf::Rest))
249	    }
250	}
