253	mod tests {
254	    use super::*;
255	
256	    /// Where a member went, for the tables.
257	    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
258	    enum Placed {
259	        Row,
260	        Used,
261	        Collapsed,
262	        Unknown,
263	    }
264	
265	    fn inherited(name: &str) -> Member {
266	        Member { name: name.to_owned(), ..Member::default() }
267	    }
268	
269	    fn ambient(name: &str) -> Member {
270	        Member { ambient: true, ..inherited(name) }
271	    }
272	
273	    fn strings(names: &[&str]) -> Vec<String> {
274	        names.iter().map(|name| (*name).to_owned()).collect()
275	    }
276	
277	    fn reading(names: &[&str]) -> Body {
278	        Body { reads: strings(names), ..Body::default() }
279	    }
280	
281	    fn named(name: &str) -> Attribute {
282	        Attribute::Named(name.to_owned())
283	    }
284	
285	    fn element(target: Target, attributes: Vec<Attribute>) -> Element {
286	        Element { target, attributes }
287	    }
288	
289	    /// The evidence of one case, owned: [`Evidence`] borrows it.
290	    #[derive(Default)]
291	    struct Owned {
292	        members: Vec<Member>,
293	        body: Option<Body>,
294	        call_sites: CallSites,
295	    }
296	
297	    impl Owned {
298	        fn decide(&self) -> Shown {
299	            decide(&Evidence { members: &self.members, body: self.body.as_ref(), call_sites: &self.call_sites })
300	        }
301	    }
302	
303	    fn with(members: Vec<Member>, body: Option<Body>) -> Owned {
304	        Owned { members, body, ..Owned::default() }
305	    }
306	
307	    fn placed(shown: &Shown, name: &str) -> Option<Placed> {
308	        let lists = [
309	            (&shown.rows, Placed::Row),
310	            (&shown.used, Placed::Used),
311	            (&shown.collapsed, Placed::Collapsed),
312	            (&shown.unknown, Placed::Unknown),
313	        ];
314	        lists.into_iter().find(|(list, _)| list.iter().any(|n| n == name)).map(|(_, placed)| placed)
315	    }
316	
317	    /// One case of a table: its label, its evidence, and where each named member must go.
318	    type Case<'a> = (&'a str, Owned, &'a [(&'a str, Placed)]);
319	
320	    /// Runs each case and checks where every named member went.
321	    fn table(cases: Vec<Case<'_>>) {
322	        for (case, evidence, expected) in cases {
323	            let shown = evidence.decide();
324	            for (name, want) in expected {
325	                assert_eq!(placed(&shown, name), Some(*want), "{case}: {name}");
326	            }
327	        }
328	    }
329	
330	    #[test]
331	    fn an_inherited_member_the_body_never_reads_stays_in_its_layer() {
332	        let evidence = with(vec![inherited("tone"), inherited("size")], Some(reading(&["size"])));
333	        let shown = evidence.decide();
334	        assert_eq!(shown.collapsed, ["tone"]);
335	        assert_eq!(shown.rows, ["size"]);
336	    }
