338	    #[test]
339	    fn a_member_the_props_type_declares_itself_is_always_a_row() {
340	        let own = |member: Member| Member { own: true, ..member };
341	        table(vec![
342	            ("never read", with(vec![own(inherited("a"))], Some(Body::default())), &[("a", Placed::Row)]),
343	            ("unknown body", with(vec![own(inherited("a"))], None), &[("a", Placed::Row)]),
344	            ("ambient", with(vec![own(ambient("a"))], Some(Body::default())), &[("a", Placed::Row)]),
345	        ]);
