378	    #[test]
379	    fn a_doc_comment_or_literal_union_orders_rows_but_never_shows_a_member_alone() {
380	        let documented = |name: &str| Member { documented: true, ..inherited(name) };
381	        let union = |name: &str| Member { literal_union: true, ..inherited(name) };
382	        table(vec![(
383	            "alone",
384	            with(vec![documented("a"), union("b"), Member { documented: true, ..ambient("c") }], Some(Body::default())),
385	            &[("a", Placed::Collapsed), ("b", Placed::Collapsed), ("c", Placed::Collapsed)],
386	        )]);
387	        let evidence = with(vec![inherited("plain"), union("u"), documented("d")], Some(reading(&["plain", "u", "d"])));
388	        assert_eq!(evidence.decide().rows, ["u", "d", "plain"]);
