391	    #[test]
392	    fn a_rest_spread_onto_a_dom_tag_is_no_evidence() {
393	        let body =
394	            Body { elements: vec![element(Target::Dom, vec![Attribute::Spread(SpreadOf::Rest)])], ..Body::default() };
395	        table(vec![(
396	            "<div {...rest} />",
397	            with(vec![inherited("a"), ambient("onClick")], Some(body)),
