402	    #[test]
403	    fn a_spread_onto_a_component_forwards_its_own_props_one_hop() {
404	        let inner = || Target::Component(strings(&["tone", "size", "variant"]));
405	        let spread =
406	            |attributes: Vec<Attribute>| Body { elements: vec![element(inner(), attributes)], ..Body::default() };
407	        let members = || vec![inherited("tone"), inherited("size"), inherited("variant"), inherited("other")];
408	        let rest = || Attribute::Spread(SpreadOf::Rest);
409	        table(vec![
410	            (
411	                "<Inner {...rest} />",
412	                with(members(), Some(spread(vec![rest()]))),
413	                &[("tone", Placed::Row), ("size", Placed::Row), ("other", Placed::Collapsed)],
414	            ),
415	            (
416	                "<Inner {...props} />",
417	                with(members(), Some(spread(vec![Attribute::Spread(SpreadOf::Props)]))),
418	                &[("variant", Placed::Row), ("other", Placed::Collapsed)],
419	            ),
420	            (
421	                "<Inner tone=\"x\" {...rest} size=\"y\" />: before kept, after subtracted",
422	                with(members(), Some(spread(vec![named("tone"), rest(), named("size")]))),
423	                &[("tone", Placed::Row), ("size", Placed::Collapsed), ("variant", Placed::Row)],
424	            ),
425	            (
426	                "<Inner {...other} />",
427	                with(members(), Some(spread(vec![Attribute::Spread(SpreadOf::Other)]))),
428	                &[("tone", Placed::Collapsed)],
429	            ),
430	        ]);
431	    }
