463	            ("2 of 10", passed(10, 2), &[("a", Placed::Row), ("b", Placed::Used)]),
464	            ("1 of 10", passed(10, 1), &[("a", Placed::Collapsed), ("b", Placed::Collapsed)]),
465	            ("1 of 2: under the floor of 2", passed(2, 1), &[("a", Placed::Collapsed)]),
466	            ("2 of 11: under 20%", passed(11, 2), &[("a", Placed::Collapsed)]),
467	            ("3 of 11", passed(11, 3), &[("a", Placed::Row), ("b", Placed::Used)]),
