471	    #[test]
472	    fn an_unknown_body_is_never_guessed() {
473	        let said = || reading(&["a"]);
474	        let handed_on = Body { handed_on: true, ..said() };
475	        let unresolved =
476	            Body { elements: vec![element(Target::Unresolved, vec![Attribute::Spread(SpreadOf::Rest)])], ..said() };
477	        let members = || {
478	            vec![
479	                inherited("a"),
480	                inherited("b"),
481	                ambient("c"),
482	                Member { required: true, ..inherited("d") },
483	                Member { default_tag: true, ..inherited("e") },
484	            ]
485	        };
486	        // What an incomplete body says still holds; only its silence is unknown, ambient or not.
487	        let incomplete: &[(&str, Placed)] = &[
488	            ("a", Placed::Row),
489	            ("b", Placed::Unknown),
490	            ("c", Placed::Unknown),
491	            ("d", Placed::Row),
492	            ("e", Placed::Row),
493	        ];
494	        let none: &[(&str, Placed)] = &[
495	            ("a", Placed::Unknown),
496	            ("b", Placed::Unknown),
497	            ("c", Placed::Unknown),
498	            ("d", Placed::Row),
499	            ("e", Placed::Row),
500	        ];
501	        table(vec![
502	            ("handed on", with(members(), Some(handed_on)), incomplete),
503	            ("spread onto an unresolved tag", with(members(), Some(unresolved)), incomplete),
504	            ("no function of its own", with(members(), None), none),
505	        ]);
506	    }
