508	    #[test]
509	    fn names_carry_no_meaning_and_order_follows_the_members() {
510	        let evidence = |names: [&str; 4]| {
511	            with(
512	                vec![inherited(names[0]), ambient(names[1]), inherited(names[2]), ambient(names[3])],
513	                Some(reading(&[names[2], names[3]])),
514	            )
515	        };
516	        let plain = evidence(["a", "b", "c", "d"]).decide();
517	        let familiar = evidence(["className", "style", "onClick", "children"]).decide();
518	        assert_eq!((plain.rows, plain.used, plain.collapsed), (strings(&["c"]), strings(&["d"]), strings(&["a", "b"])));
519	        assert_eq!(familiar.rows, ["onClick"]);
520	        assert_eq!(familiar.used, ["children"]);
521	        assert_eq!(familiar.collapsed, ["className", "style"]);
522	        assert_eq!(Owned::default().decide(), Shown::default());
523	        let twice = with(vec![inherited("a"), ambient("a")], Some(reading(&["a"]))).decide();
524	        assert_eq!((twice.rows, twice.used), (strings(&["a"]), Vec::new()));
525	    }
526	}
