    iface: &CollectedInterface,
    react_file: &Utf8Path,
    ctx: &'a ResolutionContext,
) -> &'a crate::named_type_index::NamedTypeIndex {
    if iface.file_path == react_file { ctx.react_index() } else { &ctx.named_types }
}

