        props: BTreeMap::new(),
        inheritance: Vec::new(),
        notable_inherited: BTreeMap::new(),
        discriminant_prop: None,
        composes: Vec::new(),
        tags: mapping.tags.clone(),
        methods: vec![],
        detected_by: mapping.rule,
        exported: mapping.exported(),
        exports: mapping.exports.clone(),
    }
}

