/// Decides where each member of `entry`'s props goes, from `inputs`, the revision's `call_sites` of the component and
/// the members its listed props and layers reach, and writes each collapsed layer's `used` list: the names that layer
/// holds which evidence puts forward and the output does not list. A DOM layer's names are its element's attributes
/// (`Inputs::dom_names`), not written to the output (ADR 0028, Output). Which props are listed or collapsed does not
/// change.
pub(crate) fn apply(entry: &mut ComponentEntry, inputs: &Inputs, call_sites: &CallSites) {
    let names = |at: usize, layer: &InheritedLayer| -> &[String] {
        match inputs.dom_names.get(at) {
            Some(dom) if layer.members.is_empty() && layer.html_element.is_some() => dom,
            _ => &layer.members,
        }
    };
    let layers: Vec<Layer<'_>> = entry
        .inheritance
        .iter()
        .enumerate()
        .map(|(at, layer)| Layer { file_name: &layer.file_name, names: names(at, layer) })
        .collect();
    let rows = entry.props.values().chain(entry.notable_inherited.values()).map(AsRef::as_ref);
    let members = props_type::members(&inputs.props_type, rows, &layers);
    let shown = decide(&Evidence { members: &members, body: inputs.body.as_ref(), call_sites });
    let listed = |name: &str| entry.props.contains_key(name) || entry.notable_inherited.contains_key(name);
    let used: BTreeSet<&str> = shown.used.iter().map(String::as_str).filter(|name| !listed(name)).collect();
    let used: Vec<Vec<String>> = layers
        .iter()
        .map(|layer| layer.names.iter().filter(|name| used.contains(name.as_str())).cloned().collect())
        .collect();
    for (layer, used) in entry.inheritance.iter_mut().zip(used) {
        layer.used = used;
    }
}

