/// that omits nothing shares the run's one list for its element.
pub(super) fn dom_layer_names(layer: &InheritedLayer, ctx: &ResolutionContext) -> Arc<[String]> {
    let Some(element) = layer.html_element.as_deref() else {
        return Arc::default();
    };
    let file = Utf8Path::new(&layer.file_name);
    let takes_ref = takes_ref(layer);
    let keep = |name: &&String| (takes_ref || name.as_str() != "ref") && !layer.omitted.contains(name);
    if !layer.omitted.is_empty() {
        return element_attribute_names(element, file, true, ctx).iter().filter(keep).cloned().collect();
    }
    let key = format!("{file}\0{element}\0layer\0{takes_ref}");
    if let Some(names) = ctx.attribute_names.get(&key) {
        note_augmentations(file, ctx);
        return names.clone();
    }
    let names: Arc<[String]> = element_attribute_names(element, file, true, ctx).iter().filter(keep).cloned().collect();
    ctx.attribute_names.insert(key, names.clone());
    names
}

