199	#[test]
200	fn watch_equals_fresh() {
201	    let (mut edits, mut moved) = (0, 0);
202	    for seed in [1_u64, 7, 42] {
203	        let dir = tempfile::Builder::new().prefix("RelevanceWatch").tempdir().unwrap();
204	        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
205	        let mut rng = Lcg(seed);
206	        let mut model = Model::new(root.clone(), &mut rng);
207	        let options = options(&root);
208	        let watch = WatchSession::new(options.clone());
209	        drop(watch.initialize());
210	        let lazy = WatchSession::lazy(options.clone());
211	        drop(lazy.initialize());
212	        let fresh = extract(&options);
213	        // Ask the lazy session for everything, so each edit has kept answers to go stale.
214	        for key in fresh.components.keys() {
215	            drop(lazy.component(key));
216	        }
217	        let mut previous = fresh;
218	        let mut history = Vec::new();
219	        for _ in 0..14 {
220	            let (edit, file) = model.edit(&mut rng);
221	            history.push(edit);
222	            drop(watch.update_file(&file));
223	            drop(lazy.update_file(&file));
224	            let fresh = extract(&options);
225	            let watched = watch.snapshot();
226	            let keys: Vec<&String> = fresh.components.keys().collect();
227	            assert_eq!(watched.components.keys().collect::<Vec<_>>(), keys, "seed {seed} after {history:?}");
228	            for (key, expected) in &fresh.components {
229	                assert_eq!(&watched.components[key], expected, "watch: {key}, seed {seed} after {history:?}");
230	                let answer = lazy.component(key).unwrap_or_else(|| panic!("lazy: no {key}"));
231	                assert_eq!(&answer.entry, expected, "lazy: {key}, seed {seed} after {history:?}");
232	            }
233	            // The model is only as strong as the evidence it moves: count the edits that change a `used` list.
234	            moved += usize::from(used(&previous) != used(&fresh));
235	            previous = fresh;
236	            edits += 1;
237	        }
238	    }
239	    assert_eq!(edits, 3 * 14);
240	    assert!(moved >= 3, "edits changed a `used` list {moved} times: the model does not exercise relevance");
241	}
