243	/// Every component's non-empty `used` lists, by component and layer.
244	fn used(output: &caliper_docgen_core::types::ExtractionOutput) -> Vec<(String, String, Vec<String>)> {
245	    let mut used = Vec::new();
246	    for (key, entry) in &output.components {
247	        for layer in entry.inheritance.iter().filter(|layer| !layer.used.is_empty()) {
248	            used.push((key.clone(), layer.type_name.clone(), layer.used.clone()));
249	        }
250	    }
251	    used
252	}
