    let dir = tempfile::Builder::new().prefix("RelevanceScope").tempdir().unwrap();
    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
    let fields: String = (0..33).map(|i| format!("d{i}?: string; ")).collect();
