19	/// A small deterministic generator: the model is reproducible without a dependency.
20	struct Lcg(u64);
21	
22	impl Lcg {
23	    fn below(&mut self, n: usize) -> usize {
24	        self.0 = self.0.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
25	        usize::try_from((self.0 >> 33) % n as u64).unwrap()
26	    }
27	}
28	
29	/// One generated project: `count` components over sources of 10 and 40 members.
30	fn project(seed: u64, count: usize) -> (tempfile::TempDir, Utf8PathBuf, Vec<String>) {
31	    let dir = tempfile::Builder::new().prefix("RelevanceModel").tempdir().unwrap();
32	    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
33	    let fields = |prefix: &str, n: usize| -> String { (0..n).map(|i| format!("{prefix}{i}?: string; ")).collect() };
34	    std::fs::write(
35	        root.join("sources.ts"),
36	        format!("export interface Small {{ {}}}\nexport interface Large {{ {}}}\n", fields("s", 10), fields("l", 40)),
37	    )
38	    .unwrap();
39	    // Ambient by path: React's declarations and Spectrum's shared DOM ones.
40	    for (dir, file, name) in
41	        [("vendor/@types/react", "dom.ts", "ReactDom"), ("vendor/@react-types/shared/src", "dom.d.ts", "SharedDom")]
42	    {
43	        std::fs::create_dir_all(root.join(dir)).unwrap();
44	        std::fs::write(root.join(dir).join(file), format!("export interface {name} {{ {}}}\n", fields("d", 33)))
45	            .unwrap();
46	    }
47	    std::fs::write(
48	        root.join("tsconfig.json"),
49	        r#"{ "compilerOptions": { "target": "ES2022", "module": "ESNext", "moduleResolution": "bundler", "jsx": "preserve", "strict": true, "skipLibCheck": true, "noEmit": true, "types": [] } }"#,
50	    )
51	    .unwrap();
52	    let mut rng = Lcg(seed);
53	    let mut components = String::from(
54	        "import type { Small, Large } from './sources';\n\
55	         import type { ReactDom } from './vendor/@types/react/dom';\n\
56	         import type { SharedDom } from './vendor/@react-types/shared/src/dom';\n",
57	    );
58	    let mut page = String::new();
59	    let mut names = Vec::new();
60	    for c in 0..count {
61	        let name = format!("C{c}");
62	        let (source, prefix, size) = if rng.below(2) == 0 { ("Small", "s", 10) } else { ("Large", "l", 40) };
63	        let base = match rng.below(3) {
64	            0 => source.to_owned(),
65	            1 => format!("Pick<{source}, '{prefix}0' | '{prefix}1'>"),
66	            _ => format!("Omit<{source}, '{prefix}0'>"),
67	        };
68	        let own: Vec<String> = (0..rng.below(3)).map(|i| format!("own{i}")).collect();
69	        let required = rng.below(2) == 0;
70	        let mut literal = String::new();
71	        for (i, prop) in own.iter().enumerate() {
72	            let mark = if required && i == 0 { "" } else { "?" };
73	            write!(literal, "{prop}{mark}: string; ").unwrap();
74	        }
75	        let dom = if rng.below(2) == 0 { "ReactDom" } else { "SharedDom" };
76	        let reads: Vec<String> = (0..rng.below(3))
77	            .map(|_| match rng.below(2) {
78	                0 => format!("{prefix}{}", rng.below(size)),
79	                _ => format!("d{}", rng.below(3)),
80	            })
81	            .collect();
82	        let body = if reads.is_empty() {
83	            "null".to_owned()
84	        } else {
85	            format!("<div>{{props.{}}}</div>", reads.join("}{props."))
86	        };
87	        writeln!(components, "export function {name}(props: {base} & {dom} & {{ {literal}}}) {{ return {body}; }}")
88	            .unwrap();
89	        writeln!(page, "import {{ {name} }} from './Components';").unwrap();
90	        let sites = rng.below(6);
91	        for site in 0..sites {
92	            let passed = match rng.below(2) {
93	                0 => format!("{prefix}{}", (site + rng.below(2)) % size),
94	                _ => format!("d{}", rng.below(2)),
95	            };
96	            writeln!(page, "export const use{name}x{site} = <{name} {passed}=\"v\" />;").unwrap();
97	        }
98	        names.push(name);
99	    }
100	    std::fs::write(root.join("Components.tsx"), components).unwrap();
101	    std::fs::write(root.join("Page.tsx"), page).unwrap();
102	    (dir, root, names)
103	}
104	
105	#[test]
106	fn both_lanes_report_the_same_relevance_for_the_same_member() {
107	    let (mut compared, mut named) = (0, 0);
108	    for seed in [1, 7, 42] {
109	        let (_dir, root, names) = project(seed, 12);
110	        for collapse in [CollapseInheritedProps::All, CollapseInheritedProps::None] {
111	            let options = PipelineOptions {
112	                src_dirs: vec![root.clone()],
113	                use_cache: false,
114	                collapse_inherited_props: collapse,
115	                html_attributes: HtmlAttributeMode::None,
116	                ..PipelineOptions::default()
117	            };
118	            let structural = extract(&options);
119	            let mut request = SemanticRequest::new(root.clone(), targets_of(&structural));
120	            request.request_timeout = Duration::from_secs(60);
121	            let outcome = resolve(request);
122	            assert_eq!(outcome.fallbacks, [], "the checker answers every component");
123	            let mut checker = structural.clone();
124	            merge_semantic_in(&mut checker, outcome, Default::default(), CollapseContext::of(&options));
