/// A component over a collapsed DOM layer (`React.ComponentProps<"button">`, React's real declarations, the default
/// modes) whose call sites pass `className` and `onClick`: the DOM layer names them in `used`, read from React's
/// declarations of the element, and the props listed stay as they were.
#[test]
fn a_collapsed_dom_layer_names_the_attributes_consumers_pass() {
    let (_dir, output) = dom_fixture();
    let button = &output.components["Button"];
    assert_eq!(button.props.keys().collect::<Vec<_>>(), ["tone"], "the listed props do not change");
    let layer = button.inheritance.iter().find(|layer| layer.html_element.as_deref() == Some("button"));
    let layer = layer.unwrap_or_else(|| panic!("no DOM layer: {:?}", button.inheritance));
    assert!(layer.members.is_empty(), "a DOM layer's members are its element's, not written: {layer:?}");
    let mut used = layer.used.clone();
    used.sort();
    assert_eq!(used, ["className", "onClick"], "{layer:?}");
}

